solution.solution.cpp:
#include <algorithm>
#include <cctype>
#include <string>
#include <utility>
#include <vector>

using Variables = std::vector<std::pair<std::string, std::string>>;

static std::string upper(const std::string& s)
{
    std::string out{ s };
    for (char& c : out) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return out;
}

std::string buildBlock(const Variables& vars)
{
    Variables unique;
    for (const auto& v : vars)
    {
        const auto same{ std::find_if(unique.begin(), unique.end(), [&](const auto& u) { return upper(u.first) == upper(v.first); }) };
        if (same != unique.end()) *same = v;
        else unique.push_back(v);
    }
    std::stable_sort(unique.begin(), unique.end(), [](const auto& a, const auto& b) { return upper(a.first) < upper(b.first); });
    std::string block;
    for (const auto& [name, value] : unique) { block += name + "=" + value; block += '\0'; }
    if (unique.empty()) block += '\0';
    block += '\0';
    return block;
}

Variables parseBlock(const std::string& block)
{
    Variables vars;
    std::size_t at{ 0 };
    while (at < block.size() && block[at] != '\0')
    {
        const std::size_t end{ block.find('\0', at) };
        const std::string entry{ block.substr(at, end - at) };
        const std::size_t eq{ entry.find('=', 1) };
        if (eq == std::string::npos) vars.push_back({ entry, "" });
        else vars.push_back({ entry.substr(0, eq), entry.substr(eq + 1) });
        if (end == std::string::npos) break;
        at = end + 1;
    }
    return vars;
}

std::string withVariable(const std::string& block, const std::string& name, const std::string& value)
{
    Variables vars{ parseBlock(block) };
    std::erase_if(vars, [&](const auto& v) { return upper(v.first) == upper(name); });
    vars.push_back({ name, value });
    return buildBlock(vars);
}

std::string withoutVariable(const std::string& block, const std::string& name)
{
    Variables vars{ parseBlock(block) };
    std::erase_if(vars, [&](const auto& v) { return upper(v.first) == upper(name); });
    return buildBlock(vars);
}

unitTests:
using namespace std::string_literals;
TEST("building a sorted block") {
    const std::string b{ buildBlock({ { "TEMP", "C:\\Temp" }, { "Path", "C:\\Tools" }, { "app_mode", "test" } }) };
    CHECK_EQ(b, "app_mode=test\0Path=C:\\Tools\0TEMP=C:\\Temp\0\0"s);
    CHECK_EQ(buildBlock({}), "\0\0"s);
}
TEST("names ignore case, the last one wins") {
    CHECK_EQ(buildBlock({ { "PATH", "a" }, { "Path", "b" } }), "Path=b\0\0"s);
}
TEST("parsing, including hidden drive entries") {
    const auto vars{ parseBlock("=C:=C:\\Work\0Path=C:\\Tools\0EMPTY=\0\0"s) };
    CHECK_EQ(vars.size(), 3u);
    if (vars.size() != 3) return;
    CHECK_EQ(vars[0].first, "=C:"s); CHECK_EQ(vars[0].second, "C:\\Work"s);
    CHECK_EQ(vars[1].first, "Path"s);
    CHECK_EQ(vars[2].second, ""s);
    CHECK(parseBlock("\0\0"s).empty());
}
TEST("editing") {
    const std::string start{ buildBlock({ { "Path", "C:\\Tools" }, { "TEMP", "C:\\Temp" } }) };
    CHECK_EQ(withVariable(start, "MODE", "fast"), "MODE=fast\0Path=C:\\Tools\0TEMP=C:\\Temp\0\0"s);
    CHECK_EQ(withVariable(start, "PATH", "D:\\Bin"), "PATH=D:\\Bin\0TEMP=C:\\Temp\0\0"s);
    CHECK_EQ(withoutVariable(start, "temp"), "Path=C:\\Tools\0\0"s);
    CHECK_EQ(withoutVariable(start, "missing"), start);
}

